var graph = { 0: [1, 2], 1: [0, 3], 2: [0, 3, 4], 3: [1, 2], 4: [2] };
var seen = { 0: true };
var queue = [0];
var order = [];
while (queue.length > 0) {
  var node = queue.shift();
  order.push(node);
  graph[node].forEach(function (next) {
    if (!seen[next]) {
      seen[next] = true;
      queue.push(next);
    }
  });
}
console.log(order);
